    CONSTRAINT connector_connections_revision_check CHECK ((revision >= 1))
    CREATE INDEX connector_connections_owner_idx ON public.connector_connections USING btree (customer_id, owner_type, owner_id, created_at DESC, id DESC) WHERE (deleted_at IS NULL)
    CREATE UNIQUE INDEX connector_connections_provider_unit_idx ON public.connector_connections USING btree (connector_id, provider_unit_id) WHERE ((deleted_at IS NULL) AND (provider_unit_id IS NOT NULL))

