    CREATE INDEX data_changes_user_idx ON public.data_changes USING btree (customer_id, ((payload ->> 'user_id'::text)), ((payload ->> 'id'::text))) WHERE ((table_name = 'requests'::text) AND ((payload ->> 'user_id'::text) IS NOT NULL))

