    CONSTRAINT simulation_cases_pkey PRIMARY KEY (id)
    CONSTRAINT simulation_cases_run_id_fkey FOREIGN KEY (run_id) REFERENCES simulation_runs(id) ON DELETE CASCADE
    CREATE INDEX simulation_cases_run_idx ON public.simulation_cases USING btree (run_id, variation)

TABLE simulation_runs
    assertion text NOT NULL DEFAULT ''::text
    cases integer NOT NULL DEFAULT 0
    config_id text NOT NULL DEFAULT ''::text
    customer_id text NOT NULL
    error text
    failed integer NOT NULL DEFAULT 0
    finished_at timestamp with time zone
    id text NOT NULL
    judge_target text NOT NULL DEFAULT ''::text
    lease_until timestamp with time zone
    mode text NOT NULL DEFAULT ''::text
    passed integer NOT NULL DEFAULT 0
    scenario text NOT NULL DEFAULT ''::text
    simulation_id text NOT NULL
    started_at timestamp with time zone NOT NULL DEFAULT now()
    state text NOT NULL DEFAULT 'running'::text
    stop_requested boolean NOT NULL DEFAULT false
    CONSTRAINT simulation_runs_pkey PRIMARY KEY (id)
    CONSTRAINT simulation_runs_simulation_id_fkey FOREIGN KEY (simulation_id) REFERENCES simulations(id) ON DELETE CASCADE
    CREATE INDEX simulation_runs_customer_idx ON public.simulation_runs USING btree (customer_id, started_at DESC)
    CREATE INDEX simulation_runs_lease_idx ON public.simulation_runs USING btree (lease_until) WHERE (state = 'running'::text)
    CREATE INDEX simulation_runs_simulation_idx ON public.simulation_runs USING btree (simulation_id, started_at DESC)

TABLE simulations
    assertion text NOT NULL DEFAULT ''::text
    caller_stt text NOT NULL DEFAULT ''::text
    caller_target text NOT NULL DEFAULT ''::text
    caller_tts text NOT NULL DEFAULT ''::text
    caller_voice text NOT NULL DEFAULT ''::text
    config_id text NOT NULL DEFAULT ''::text
    created_at timestamp with time zone NOT NULL DEFAULT now()
    customer_id text NOT NULL
    deleted_at timestamp with time zone
    id text NOT NULL
    judge_target text NOT NULL DEFAULT ''::text
    max_turns integer NOT NULL DEFAULT 12
    mode text NOT NULL DEFAULT 'text'::text
    name text NOT NULL
    scenario text NOT NULL DEFAULT ''::text
    tags jsonb NOT NULL DEFAULT '{}'::jsonb
    updated_at timestamp with time zone NOT NULL DEFAULT now()
    variations integer NOT NULL DEFAULT 1
    CONSTRAINT simulations_pkey PRIMARY KEY (id)
    CREATE INDEX simulations_customer_idx ON public.simulations USING btree (customer_id, created_at DESC) WHERE (deleted_at IS NULL)

TABLE sip_trunks
    codecs text[] NOT NULL DEFAULT '{}'::text[]
    created_at timestamp with time zone NOT NULL DEFAULT now()
    customer_id text NOT NULL
    host text NOT NULL
    id text NOT NULL
    late_offer boolean NOT NULL DEFAULT false
    name text NOT NULL
    password_kek_version integer NOT NULL DEFAULT 0
    password_sealed bytea NOT NULL DEFAULT '\x'::bytea
    port integer NOT NULL
    transport text NOT NULL
    updated_at timestamp with time zone NOT NULL DEFAULT now()
    username text NOT NULL
    CONSTRAINT sip_trunks_customer_id_id_key UNIQUE (customer_id, id)
    CONSTRAINT sip_trunks_pkey PRIMARY KEY (id)
    CONSTRAINT sip_trunks_transport_check CHECK ((transport = ANY (ARRAY['udp'::text, 'tcp'::text, 'tls'::text])))
    CREATE INDEX sip_trunks_customer_idx ON public.sip_trunks USING btree (customer_id, created_at DESC)

TABLE skills
    capture_video boolean NOT NULL DEFAULT false
    config_id text NOT NULL DEFAULT ''::text
    created_at timestamp with time zone NOT NULL DEFAULT now()
    customer_id text NOT NULL
    deadline_ms bigint NOT NULL DEFAULT 0
    deleted_at timestamp with time zone
    description text NOT NULL
    files jsonb NOT NULL DEFAULT '{}'::jsonb
    id text NOT NULL
    instructions text NOT NULL
    name text NOT NULL
    updated_at timestamp with time zone NOT NULL DEFAULT now()
    CONSTRAINT skills_pkey PRIMARY KEY (id)
    CREATE UNIQUE INDEX skills_name_idx ON public.skills USING btree (customer_id, config_id, name) WHERE (deleted_at IS NULL)

TABLE stream_app_tokens
    api_key text NOT NULL
    customer_id text NOT NULL
    expires_at timestamp with time zone NOT NULL
    kek_version integer NOT NULL
    stream_app_pk bigint NOT NULL
    token_sealed bytea NOT NULL
    updated_at timestamp with time zone NOT NULL DEFAULT now()
    CONSTRAINT stream_app_tokens_pkey PRIMARY KEY (stream_app_pk)

TABLE stream_fallback_uses
    customer_id text NOT NULL
    first_at timestamp with time zone NOT NULL
    last_at timestamp with time zone NOT NULL
    uses bigint NOT NULL
    CONSTRAINT stream_fallback_uses_pkey PRIMARY KEY (customer_id)

TABLE stream_trunks
    bridge_password_kek_version integer NOT NULL
    bridge_password_sealed bytea NOT NULL
    bridge_uri text NOT NULL
    bridge_username text NOT NULL
    created_at timestamp with time zone NOT NULL DEFAULT now()
    customer_id text NOT NULL
    id text NOT NULL
    own boolean NOT NULL DEFAULT false
    stream_app_pk bigint
    vendor text NOT NULL
    CONSTRAINT stream_trunks_pkey PRIMARY KEY (id)
    CREATE INDEX stream_trunks_group_idx ON public.stream_trunks USING btree (customer_id, stream_app_pk, vendor)

TABLE telephony_suspensions
    customer_id text NOT NULL
    reason text NOT NULL
    suspended_at timestamp with time zone NOT NULL
    suspended_by text NOT NULL
    CONSTRAINT telephony_suspensions_pkey PRIMARY KEY (customer_id)

TABLE usage_claims
    claimed_at timestamp with time zone NOT NULL DEFAULT now()
    shard text NOT NULL
    usage_id uuid NOT NULL
    CONSTRAINT usage_claims_pkey PRIMARY KEY (usage_id)

TABLE usage_resets
    actor text NOT NULL
    api_key text NOT NULL DEFAULT ''::text
    app_id text NOT NULL DEFAULT ''::text
    baseline_micros bigint NOT NULL
    category text NOT NULL DEFAULT ''::text
    created_at timestamp with time zone NOT NULL DEFAULT now()
    id bigint NOT NULL DEFAULT nextval('usage_resets_id_seq'::regclass)
    interval text NOT NULL
    organization_id text NOT NULL
    reason text NOT NULL
    subject text NOT NULL
    user_id text NOT NULL DEFAULT ''::text
    window_start timestamp with time zone NOT NULL
    CONSTRAINT usage_resets_baseline_micros_check CHECK ((baseline_micros >= 0))
    CONSTRAINT usage_resets_organization_id_check CHECK ((organization_id <> ''::text))
    CONSTRAINT usage_resets_pkey PRIMARY KEY (id)
    CREATE INDEX usage_resets_organization_idx ON public.usage_resets USING btree (organization_id, window_start)

TABLE user_phone_history
    customer_id text NOT NULL
    linked_at timestamp with time zone NOT NULL
    since timestamp with time zone
    stream_app_pk bigint NOT NULL
    user_id text NOT NULL
    CONSTRAINT user_phone_history_customer_id_stream_app_pk_user_id_fkey FOREIGN KEY (customer_id, stream_app_pk, user_id) REFERENCES user_phones(customer_id, stream_app_pk, user_id) ON DELETE CASCADE
    CONSTRAINT user_phone_history_pkey PRIMARY KEY (customer_id, stream_app_pk, user_id)

TABLE user_phones
    created_at timestamp with time zone NOT NULL
    customer_id text NOT NULL
    phone text NOT NULL
    stream_app_pk bigint NOT NULL
    updated_at timestamp with time zone NOT NULL
    user_id text NOT NULL
    CONSTRAINT user_phones_phone_check CHECK ((phone <> ''::text))
    CONSTRAINT user_phones_pkey PRIMARY KEY (customer_id, stream_app_pk, user_id)
    CONSTRAINT user_phones_user_id_check CHECK ((user_id <> ''::text))
    CREATE UNIQUE INDEX user_phones_phone ON public.user_phones USING btree (customer_id, stream_app_pk, phone)

TABLE users
    claim_finished_at timestamp with time zone
    claimed_at timestamp with time zone
    claimed_by text
    created_at timestamp with time zone NOT NULL DEFAULT now()
    custom jsonb NOT NULL DEFAULT '{}'::jsonb
    customer_id text NOT NULL
    email text
    id text NOT NULL
    kind text NOT NULL
    minted boolean NOT NULL DEFAULT false
    minted_elsewhere boolean
    name text NOT NULL DEFAULT ''::text
    refresh_secret_hash bytea
    shard text
    timezone text
    CONSTRAINT users_pkey PRIMARY KEY (customer_id, id)
    CREATE INDEX users_claimed_idx ON public.users USING btree (customer_id, claimed_by) WHERE (claimed_by IS NOT NULL)
    CREATE INDEX users_customer_idx ON public.users USING btree (customer_id, created_at DESC)

TABLE voice_bindings
    created_at timestamp with time zone NOT NULL DEFAULT now()
    error text NOT NULL DEFAULT ''::text
    external_id text NOT NULL DEFAULT ''::text
    id text NOT NULL
    provider text NOT NULL
    state text NOT NULL DEFAULT 'pending'::text
    synced_at timestamp with time zone
    updated_at timestamp with time zone NOT NULL DEFAULT now()
    voice_id text NOT NULL
    CONSTRAINT voice_bindings_pkey PRIMARY KEY (id)
    CONSTRAINT voice_bindings_voice_id_fkey FOREIGN KEY (voice_id) REFERENCES voices(id) ON DELETE CASCADE
    CREATE INDEX voice_bindings_external_idx ON public.voice_bindings USING btree (provider, external_id)
    CREATE UNIQUE INDEX voice_bindings_provider_idx ON public.voice_bindings USING btree (voice_id, provider)

TABLE voice_samples
    bytes bigint NOT NULL DEFAULT 0
    content_type text NOT NULL DEFAULT ''::text
    created_at timestamp with time zone NOT NULL DEFAULT now()
    id text NOT NULL
    object_key text NOT NULL
    transcript text NOT NULL DEFAULT ''::text
    voice_id text NOT NULL
    CONSTRAINT voice_samples_pkey PRIMARY KEY (id)
    CONSTRAINT voice_samples_voice_id_fkey FOREIGN KEY (voice_id) REFERENCES voices(id) ON DELETE CASCADE
    CREATE INDEX voice_samples_voice_idx ON public.voice_samples USING btree (voice_id, created_at)

TABLE voices
    created_at timestamp with time zone NOT NULL DEFAULT now()
    customer_id text NOT NULL
    deleted_at timestamp with time zone
    description text NOT NULL DEFAULT ''::text
    id text NOT NULL
    name text NOT NULL
    updated_at timestamp with time zone NOT NULL DEFAULT now()
    CONSTRAINT voices_pkey PRIMARY KEY (id)
    CREATE INDEX voices_customer_idx ON public.voices USING btree (customer_id, created_at DESC)
    CREATE UNIQUE INDEX voices_name_idx ON public.voices USING btree (customer_id, name) WHERE (deleted_at IS NULL)
